import{_ as a,o,c as r,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const c=JSON.parse('{"title":"第 20 章 记忆系统进阶：长期协作上下文（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第20章 记忆系统进阶：长期协作上下文（易懂版）.md","filePath":"easy/第20章 记忆系统进阶：长期协作上下文（易懂版）.md"}'),n={name:"easy/第20章 记忆系统进阶：长期协作上下文（易懂版）.md"};function s(l,t,d,i,h,u){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="第-20-章-记忆系统进阶-长期协作上下文-易懂版" tabindex="-1">第 20 章 记忆系统进阶：长期协作上下文（易懂版） <a class="header-anchor" href="#第-20-章-记忆系统进阶-长期协作上下文-易懂版" aria-label="Permalink to &quot;第 20 章 记忆系统进阶：长期协作上下文（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 [第 20 章 记忆系统进阶：长期协作上下文（完整版）](../../bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 20 章 记忆系统进阶：长期协作上下文.md)。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>基础记忆是&quot;记住你的偏好&quot;；进阶记忆是&quot;记住整个项目的来龙去脉&quot;——让长期大项目不跑偏。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>接手一个跟了半年的项目，最重要的不是&quot;客户喜欢喝什么茶&quot;，而是<strong>项目背景、关键决策、踩过的坑、下一步计划</strong>——这些就是&quot;项目上下文&quot;。</p><p>进阶记忆 = <strong>把项目从头到尾的&quot;上下文&quot;管起来</strong>。</p><h2 id="核心就-3-件事" tabindex="-1">核心就 3 件事 <a class="header-anchor" href="#核心就-3-件事" aria-label="Permalink to &quot;核心就 3 件事&quot;">​</a></h2><ol><li><strong>记录决策</strong>：为什么选 A 方案不选 B？<strong>写下来，防止三个月后重复讨论</strong>。</li><li><strong>记录进展</strong>：项目做到哪一步、卡在哪、下一步干啥——<strong>随时接上，不用重新考古</strong>。</li><li><strong>记录约定</strong>：术语怎么叫、格式用什么、谁负责什么——<strong>团队口径一致</strong>。</li></ol><h2 id="怎么建立-项目记忆" tabindex="-1">怎么建立&quot;项目记忆&quot;？ <a class="header-anchor" href="#怎么建立-项目记忆" aria-label="Permalink to &quot;怎么建立&quot;项目记忆&quot;？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时机</th><th>记什么</th></tr></thead><tbody><tr><td>项目启动</td><td>目标、范围、参与人、成功标准</td></tr><tr><td>每次关键讨论</td><td>结论 + 为什么这么定</td></tr><tr><td>每完成一阶段</td><td>交付了什么、下一步是什么</td></tr><tr><td>踩坑之后</td><td>什么坑、怎么避免再踩</td></tr></tbody></table><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p>项目启动时告诉我：&quot;记住：这个项目叫<code>官网改版</code>，目标是 9 月上线，预算 5 万，我负责内容，小王负责设计，成功标准是转化率提升 10%。&quot; 之后每次聊这个项目，我都能<strong>对上号</strong>，不用你反复解释背景。</p></blockquote><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 只记结论不记原因——<strong>几个月后&quot;为什么&quot;忘了，结论也守不住</strong>；</li><li>❌ 记了不更新——<strong>项目变了，记忆还停在三个月前</strong>；</li><li>❌ 把记忆当保险箱——<strong>重要机密别全写进记忆</strong>，控制敏感内容。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>进阶记忆 = 记决策 + 记进展 + 记约定，让长期项目有&quot;共同上下文&quot;。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>把你现在最大的项目说三句给我：<strong>目标？卡点？下一步？</strong> 我记下，下次直接接着聊。</p><p>👉 [下一章：岗位路线图，不同岗位怎么把我用深（易懂版）](第21章 岗位路线图：不同岗位如何把我用深（易懂版）.md)</p>',20)])])}const q=a(n,[["render",s]]);export{c as __pageData,q as default};
